import { Component, inject, OnInit, OnDestroy, effect } from '@angular/core';
import { DOCUMENT } from '@angular/common';
import { Router, RouterLink } from '@angular/router';
import { InstitutionalBarComponent } from '../../components/institutional-bar/institutional-bar.component';
import { MainNavbarComponent } from '../../components/main-navbar/main-navbar.component';
import { FooterSectionComponent } from '../../components/footer-section/footer-section.component';
import { AuthService } from '../../services/auth.service';
import { ThemeService } from '../../services/theme.service';

@Component({
  selector: 'app-decreto',
  imports: [
    RouterLink,
    InstitutionalBarComponent,
    MainNavbarComponent,
    FooterSectionComponent
  ],
  templateUrl: './decreto.html',
  styleUrl: './decreto.scss',
})
export class Decreto implements OnInit, OnDestroy {
  private readonly themeService = inject(ThemeService);
  private readonly document = inject(DOCUMENT);
  protected readonly authService = inject(AuthService);
  private readonly router = inject(Router);
  private redirecting = false;
  private readonly targetRoute = ['/inversores/autorizaciones/nueva'];

  constructor() {
    effect(() => {
      const isModalOpen = this.authService.isAuthModalOpen();
      const currentUser = this.authService.currentUser();

      if (!isModalOpen && !currentUser) {
        this.redirecting = false;
      }
      if (currentUser && this.redirecting) {
        this.redirecting = false;
        this.authService.closeModal();
        this.router.navigate(this.targetRoute);
      }
    });
  }

  ngOnInit(): void {
    this.document.documentElement.setAttribute('data-bs-theme', 'light');
  }

  ngOnDestroy(): void {
    this.themeService.refreshTheme();
  }

  onComenzarSolicitud(event: Event) {
    event.preventDefault();
    if (this.authService.currentUser()) {
      this.authService.closeModal();
      this.router.navigate(this.targetRoute);
    } else {
      this.redirecting = true;
      this.authService.openModal();
    }
  }
}
